#include <stdint.h>
#include <stdbool.h>

static volatile uint32_t timer_ticks = 0;
static volatile bool button_event = false;

void timer_interrupt_handler(void) {
  // Kurz: Ereignis erfassen; keine Anzeige und kein delay in der ISR.
  timer_ticks++;
}

void button_interrupt_handler(void) {
  // Kurz: Die Hauptschleife verarbeitet die Aktion später.
  button_event = true;
}

int main(void) {
  // Startup-Code hat Data, BSS und Stack bereits vorbereitet.
  initialise_hardware();

  for (;;) {
    if (button_event) {
      button_event = false;
      handle_button_action();
    }

    if (timer_ticks > 0) {
      timer_ticks--;
      update_state_machine();
    }

    update_display_without_blocking();
  }
}
